using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using MyDoc.Data;
using MyDoc.Models;
using MyDoc.Services;
namespace MyDoc.Tests;
public sealed class AuthorizationTests:IDisposable{readonly SqliteConnection connection=new("DataSource=:memory:");readonly DocSpaceDbContext db;public AuthorizationTests(){connection.Open();db=new(new DbContextOptionsBuilder<DocSpaceDbContext>().UseSqlite(connection).Options);db.Database.EnsureCreated();var alice=new User{Name="Alice",Email="alice@test"};var bob=new User{Name="Bob",Email="bob@test"};db.Users.AddRange(alice,bob);db.SaveChanges();db.Documents.Add(new Document{OwnerId=alice.Id,Title="Private",ContentHtml="<p>x</p>",CreatedAtUtc=DateTime.UtcNow,UpdatedAtUtc=DateTime.UtcNow});db.SaveChanges();}[Fact]public async Task Private_document_is_inaccessible_to_non_owner(){var auth=new DocumentAuthorizationService(db);Assert.Equal(DocumentAccess.None,await auth.GetAccessAsync(1,2));}[Fact]public async Task Shared_viewer_cannot_edit(){db.DocumentShares.Add(new DocumentShare{DocumentId=1,UserId=2,Permission=SharePermission.Viewer});await db.SaveChangesAsync();var auth=new DocumentAuthorizationService(db);Assert.Equal(DocumentAccess.Viewer,await auth.GetAccessAsync(1,2));}[Fact]public async Task Owner_and_shared_editor_have_expected_access(){db.DocumentShares.Add(new DocumentShare{DocumentId=1,UserId=2,Permission=SharePermission.Editor});await db.SaveChangesAsync();var auth=new DocumentAuthorizationService(db);Assert.Equal(DocumentAccess.Owner,await auth.GetAccessAsync(1,1));Assert.Equal(DocumentAccess.Editor,await auth.GetAccessAsync(1,2));}public void Dispose(){db.Dispose();connection.Dispose();}}
